#!/usr/bin/env bash
# Container start-up for SASM Foundations assignment 1.
#
# This brings the server up in the state you inherit from the previous
# administrator. That state is not clean: exactly one thing about it is wrong,
# and part of your assignment is to find out what, explain it and repair it.
#
# The payload below is encoded on purpose. You are of course free to decode it.
# It will tell you the answer and teach you nothing, and the practical exam in
# January will not come with a script you can read. Your call.
set -u

PAYLOAD='

'
# Only on the very first start of this container. A docker compose stop/start
# keeps your repair; only docker compose down gives you a fresh server again.
FIRST_BOOT=/var/lib/sasm/first-boot-done
if [ ! -e "$FIRST_BOOT" ]; then
  printf '%s' "$PAYLOAD" | base64 -d | SASM_STUDENT="${SASM_STUDENT:-unknown}" bash
  mkdir -p /var/lib/sasm && touch "$FIRST_BOOT"
fi

echo "Server ${HOSTNAME} is up."
exec tail -f /dev/null
